// ⚠ DO NOT REMOVE — Scope guard. DXF2BIM demo film, ENGLISH (FILM_PLAN §10, spec prompts/FILM_DXF2BIM_EN.md). Read <out>/film.log and <out>/film.page.log after
// every run: exit code is not evidence. CPU only (headless chromium, SwiftShader GL), no GPU lock.
// ONE recorder, several pages in one browser: A = Modeller with the Duplex resident; S = the std sheets as ezdxf drew them (render_sheets.py);
// B = Modeller importing the MARKED std set (editor, verdict, Convert); C = Modeller importing the RAW std set (= the std2d output, the marking layer
// absent) and filling it through the Drawing metadata editor. Pages switch only while a card covers the screen (the same card is on both pages
// in the same tick), so no frame of a half-loaded page is recorded. A wait that shows a spinner is CUT (jump()). Every number the voices say is a
// §FILM_FACT read in this take, or a facts/ log line named in the TSV source column.
// Run: MODELLER_REPO=<bim-ootb worktree on the L4 editor> DXF2BIM_BC=<BIMCompiler master worktree> FILM_WORK=~/Videos/dxf2bim_film_work
//      [BEAT_MIN='{"c1":8.2,…}'] node film_dxf2bim_modeller.js <outDir>   -> <outDir>/film.mp4 (24 fps, 1920x1080) + film.log
'use strict';
const os = require('os'), http = require('http'), fs = require('fs'), path = require('path'), { execFileSync } = require('child_process');
const { chromium } = require(path.join(os.homedir(), 'bim-ootb/tests/node_modules/playwright'));
const REPO = process.env.MODELLER_REPO || '/tmp/wt-film-dxf';
const BC = process.env.DXF2BIM_BC || '/tmp/wt-bc-film';
const WORK = process.env.FILM_WORK || path.join(os.homedir(), 'Videos/dxf2bim_film_work');
const OUT = path.resolve(process.argv[2] || '.'); const FR = path.join(OUT, 'frames'); fs.mkdirSync(FR, { recursive: true });
const LOG = [], PAGELOG = [];
const say = s => { LOG.push(s); console.log(s); };
const fact = (k, v) => say('§FILM_FACT ' + k + '=' + String(v).replace(/\s+/g, ' ').slice(0, 400));
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript', '.json': 'application/json', '.wasm': 'application/wasm', '.css': 'text/css', '.svg': 'image/svg+xml', '.png': 'image/png', '.db': 'application/octet-stream' };
const server = http.createServer((req, res) => {
  const p = decodeURIComponent(req.url.split('?')[0]);
  const fp = p.startsWith('/__film/') ? path.join(WORK, 'sheets', p.slice(8) || 'index.html') : path.join(REPO, p);
  fs.stat(fp, (e, st) => { if (e || st.isDirectory()) { res.writeHead(404); res.end('404'); return; }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(fp)] || 'application/octet-stream', 'Content-Length': st.size }); fs.createReadStream(fp).pipe(res); });
});
// inputs (regenerated by the BIMCompiler master chain before the take; see facts.md)
const OUTD = path.join(BC, 'tests/dxf2bim/out');
const MARKED = ['marked_std/DX_FLOOR_GF_marked.dxf', 'marked_std/DX_FLOOR_FF_marked.dxf', 'marked_std_shell/DX_FRONT_shell.dxf', 'marked_std_shell/DX_REAR_shell.dxf',
  'marked_std_shell/DX_LEFT_shell.dxf', 'marked_std_shell/DX_RIGHT_shell.dxf', 'marked_std/DX_ROOF_marked.dxf', 'marked_std/DX_SECTION_marked.dxf'].map(f => path.join(OUTD, f));
const SHEETS = ['FLOOR_GF', 'FLOOR_FF', 'FRONT', 'REAR', 'LEFT', 'RIGHT', 'ROOF', 'SECTION'];
const RAW = SHEETS.map(n => path.join(BC, '2D_Layout/output/STD/DX_' + n + '_std.dxf'));
const MK = require(path.join(BC, 'deploy/dev/dxf2marks.js')), DxfParser = require(path.join(BC, 'deploy/dev/dxf-parser.js'));
// the marking layer removed (TEXT/MTEXT on DXF2BIM-MARK in ENTITIES): the raw file must equal it byte for byte
function stripMarks(text) {
  const L = text.split(/\r?\n/), out = []; let inEnt = false, i = 0;
  while (i + 1 < L.length) {
    const c = L[i].trim(), v = L[i + 1].trim();
    if (c === '0' && v === 'SECTION' && (L[i + 3] || '').trim() === 'ENTITIES') inEnt = true; else if (inEnt && c === '0' && v === 'ENDSEC') inEnt = false;
    if (inEnt && c === '0' && (v === 'TEXT' || v === 'MTEXT')) { let j = i + 2, mk = false; while (j + 1 < L.length && L[j].trim() !== '0') { if (L[j].trim() === '8' && L[j + 1].trim() === 'DXF2BIM-MARK') mk = true; j += 2; }
      if (!mk) for (let k = i; k < j; k++) out.push(L[k]); i = j; continue; }
    out.push(L[i], L[i + 1]); i += 2;
  }
  for (; i < L.length; i++) out.push(L[i]);
  return out.join(text.indexOf('\r\n') >= 0 ? '\r\n' : '\n');
}
// the values the editor is fed in the raw chapter = the marked set's own markings (what the model-derived set states), per raw sheet name
const ORIG = {}; MARKED.forEach((f, i) => { ORIG[path.basename(RAW[i])] = MK.readMarks(new DxfParser().parseSync(fs.readFileSync(f, 'utf8')).entities)
  .map(m => { const p = /^@([A-Z]+)=(.*)$/.exec(m.raw.replace(/\s+@BY=\S+$/, '')); return { key: p[1], value: p[2], x: m.x, y: m.y }; }); });

