    restore(s) { if (typing) clearInterval(typing); const fc = document.getElementById('__fc'); if (fc) fc.style.visibility = 'hidden'; cd.style.transition = 'none'; cd.className = s.cls; cd.innerHTML = s.html; cd.querySelectorAll('.row').forEach((e, i) => { e.textContent = s.rows[i] || ''; }); cd.classList.add('on'); cd.offsetHeight; cd.style.transition = ''; window.__cardTag = s.tag; },
